{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "대단위공원 일부 조성 시 공원관리청 직접 설치 사업면적이 10,000㎡ 미만이라는 이유만으로 설치가 제한되는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "대단위공원의 경우 시장이 공익상 필요하다고 인정하면 도시관리계획으로 결정된 공원면적의 일부에 공원시설을 설치할 수 있습니다. 이 경우 사업시행면적은 10,000제곱미터 이상으로 하여야 하나, 공원관리청이 직접 설치할 때에는 그 면적 기준을 적용하지 않습니다. 따라서 공원관리청이 직접 설치하는 사업면적이 8,000㎡로 10,000㎡보다 작더라도, 그 이유만으로 일부 설치가 막히지는 않습니다.",
          "b_ids": "도시공원:제5조제2항단서,도시공원:제5조제3항,도시공원:제2조제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
